/* ---------- helpers ---------- */
const bgC = document.getElementById('bg'), fxC = document.getElementById('fx');
const bgx = bgC.getContext('2d'), fx = fxC.getContext('2d');
const TAU = Math.PI * 2, PI = Math.PI;
const clamp = (x, a, b) => (x < a ? a : x > b ? b : x);
const lerp = (a, b, t) => a + (b - a) * t;
const sstep = (a, b, x) => { const t = clamp((x - a) / (b - a), 0, 1); return t * t * (3 - 2 * t); };
const mixc = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
const rgb = c => 'rgb(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ')';
const rgba = (c, a) => 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + (+a).toFixed(3) + ')';

function mulberry(seed) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const perm = new Uint8Array(512);
(() => {
  const r = mulberry(1337), p = [];
  for (let i = 0; i < 256; i++) p.push(i);
  for (let i = 255; i > 0; i--) { const j = (r() * (i + 1)) | 0, t = p[i]; p[i] = p[j]; p[j] = t; }
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
})();
const hsh = (x, y, z) => perm[perm[perm[x & 255] + (y & 255)] + (z & 255)] / 255;
const fade = t => t * t * t * (t * (t * 6 - 15) + 10);
function noise3(x, y, z) {
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const u = fade(x - xi), v = fade(y - yi), w = fade(z - zi);
  const a = hsh(xi, yi, zi), b = hsh(xi + 1, yi, zi), c = hsh(xi, yi + 1, zi), d = hsh(xi + 1, yi + 1, zi);
  const e = hsh(xi, yi, zi + 1), f = hsh(xi + 1, yi, zi + 1), g = hsh(xi, yi + 1, zi + 1), h = hsh(xi + 1, yi + 1, zi + 1);
  return lerp(lerp(lerp(a, b, u), lerp(c, d, u), v), lerp(lerp(e, f, u), lerp(g, h, u), v), w);
}
function curl(x, y, z, out) {
  const e = 0.03;
  out[0] = (noise3(x, y + e, z) - noise3(x, y - e, z)) / (2 * e);
  out[1] = -(noise3(x + e, y, z) - noise3(x - e, y, z)) / (2 * e);
}

/* ---------- shared state ---------- */
// Bowl plane coordinates: u = right, v = toward viewer, h = height above the broth (all in units of R).
const G = { W: 0, H: 0, dpr: 1, cx: 0, cy: 0, R: 300, u: 1, k: 0.46, ce: 0.888, by: 0, m: 0, outline: null, drip: null, specks: [] };
const RI = 0.955, BR = 0.89, BD = 0.13, FR = 0.42, HB = 0.8;
const light = { x: -0.95, y: -1.05, I: 1, az: -2.3, saz: 2.7 };
const ptr = { x: 0, y: 0, vx: 0, vy: 0, on: false, near: 0 };
const par = { x: 0, y: 0 };
const anim = { t: 0, last: 0, raf: 0, q: 1, ft: 16.7, slow: 0 };
let reduce = false, layers = null, stateDirty = false;
const dead = {};

function safe(name, fn, a, b, c) {
  if (dead[name]) return;
  fx.save();
  try { fn(a, b, c); } catch (e) { dead[name] = 1; stateDirty = true; if (window.console) console.error('[ramen] ' + name, e); }
  fx.restore();
}

const prof = t => FR + (1 - FR) * Math.pow(Math.max(0, 1 - Math.pow(t, 1.7)), 0.6);
const P = (u, v, h) => [G.cx + u * G.R, G.by + v * G.R * G.k - (h || 0) * G.R * G.ce];
const wallPt = (th, t) => {
  const r = prof(t) * G.R;
  return [G.cx + r * Math.cos(th), G.cy + t * HB * G.R * G.ce + G.k * r * Math.sin(th)];
};
function rr(c, x, y, w, h, r) {
  r = Math.max(0, Math.min(r, w / 2, h / 2));
  c.moveTo(x + r, y);
  c.arcTo(x + w, y, x + w, y + h, r);
  c.arcTo(x + w, y + h, x, y + h, r);
  c.arcTo(x, y + h, x, y, r);
  c.arcTo(x, y, x + w, y, r);
  c.closePath();
}

/* ---------- layout & static geometry ---------- */
const tmp = document.createElement('canvas'), tmpg = tmp.getContext('2d');

function tryDo(fn) {
  try { fn(); } catch (e) { if (window.console) console.error('[ramen] ' + (fn.name || 'build'), e); }
}

function makeLayer(x, y, w, h) {
  const d = G.dpr;
  x = Math.round(x * d) / d; y = Math.round(y * d) / d;
  const c = document.createElement('canvas');
  c.width = Math.ceil(w * d); c.height = Math.ceil(h * d);
  const g = c.getContext('2d');
  g.setTransform(d, 0, 0, d, -x * d, -y * d);
  return { c, g, x, y, w: c.width / d, h: c.height / d };
}

// Exact lower silhouette of the bowl (envelope of the projected wall circles), in units of R.
function buildOutline() {
  const N = 120, M = 260, k = G.k, ce = G.ce, ys = new Float32Array(N + 1);
  for (let i = 0; i <= N; i++) {
    const X = Math.abs(-1 + 2 * i / N);
    let best = 0;
    for (let j = 0; j <= M; j++) {
      const t = j / M, r = prof(t);
      if (r < X) break;
      const y = t * HB * ce + k * Math.sqrt(Math.max(0, r * r - X * X));
      if (y > best) best = y;
    }
    ys[i] = best;
  }
  G.outline = ys;
}

// Depth (0..1 down the wall) of the rust glaze edge for each angle across the front of the bowl.
function buildDrip() {
  const r = mulberry(99), N = 120, arr = new Float32Array(N + 1), tongues = [];
  for (let i = 0; i < 9; i++) tongues.push({ c: 0.18 + r() * 2.8, w: 0.09 + r() * 0.15, L: 0.09 + r() * 0.36 });
  for (let i = 0; i <= N; i++) {
    const th = PI * i / N;
    let t = 0.13 + 0.05 * (noise3(th * 1.7, 3.3, 0.5) - 0.5) * 2;
    for (const q of tongues) {
      const dd = Math.abs(th - q.c) / q.w;
      if (dd < 1) t = Math.max(t, 0.13 + q.L * Math.pow(1 - dd * dd, 0.65));
    }
    arr[i] = t;
  }
  G.drip = arr;
}

function buildSpecks() {
  const r = mulberry(4242), arr = [];
  for (let i = 0; i < 380; i++) {
    const p = wallPt(r() * PI, 0.05 + r() * 0.95);
    arr.push([p[0], p[1], 0.7 + r() * 1.1, r() < 0.55 ? 0 : 1, 0.14 + r() * 0.34]);
  }
  G.specks = arr;
}

function buildLayers() {
  const R = G.R, r = mulberry(20240611);
  const x = G.cx - 1.32 * R, y = G.cy - 1.0 * R, w = 2.64 * R, h = 1.72 * R;
  const con = makeLayer(x, y, w, h), glo = makeLayer(x, y, w, h);
  tryDo(() => drawNoodles(con.g, glo.g, r));
  tryDo(() => drawToppings(con.g, glo.g, r));
  layers = { contents: con, gloss: glo };
  const s = Math.ceil(2 * 0.8 * R * G.dpr) + 4;
  tmp.width = s; tmp.height = s;
}

function layout() {
  const W = Math.max(1, window.innerWidth), H = Math.max(1, window.innerHeight);
  const d = Math.min(window.devicePixelRatio || 1, 2);
  G.W = W; G.H = H; G.dpr = d;
  G.R = Math.min(W * 0.4, H * 0.36);
  G.u = G.R / 380;
  G.k = 0.46; G.ce = Math.sqrt(1 - G.k * G.k);
  G.cx = W / 2; G.cy = H * 0.585;
  G.by = G.cy + BD * G.R * G.ce;
  G.m = Math.round(0.04 * Math.min(W, H));
  fxC.width = Math.round(W * d); fxC.height = Math.round(H * d);
  bgC.width = Math.round((W + 2 * G.m) * d); bgC.height = Math.round((H + 2 * G.m) * d);
  bgC.style.width = (W + 2 * G.m) + 'px'; bgC.style.height = (H + 2 * G.m) + 'px';
  bgC.style.left = -G.m + 'px'; bgC.style.top = -G.m + 'px';
  stateDirty = false;
  tryDo(buildOutline); tryDo(buildDrip); tryDo(buildSpecks); tryDo(buildLayers); tryDo(drawBackground);
}

/* ---------- background: room, table, bokeh (static, parallaxed by CSS) ---------- */
function drawBackground() {
  const g = bgx, W = G.W, H = G.H, R = G.R, cx = G.cx, cy = G.cy, m = G.m, d = G.dpr;
  const r = mulberry(777);
  g.setTransform(d, 0, 0, d, m * d, m * d);
  g.globalCompositeOperation = 'source-over';
  g.globalAlpha = 1;
  const X0 = -m, Y0 = -m, FW = W + 2 * m, FH = H + 2 * m;
  g.clearRect(X0, Y0, FW, FH);

  let gr = g.createLinearGradient(0, Y0, 0, Y0 + FH);
  gr.addColorStop(0, '#06090b'); gr.addColorStop(0.42, '#0c0908'); gr.addColorStop(0.62, '#130a06'); gr.addColorStop(1, '#090504');
  g.fillStyle = gr; g.fillRect(X0, Y0, FW, FH);

  // cool ambient from the upper right, against the warm key light
  gr = g.createRadialGradient(W * 0.88, H * 0.05, 0, W * 0.88, H * 0.05, Math.max(W, H) * 0.7);
  gr.addColorStop(0, 'rgba(40,86,112,0.16)'); gr.addColorStop(1, 'rgba(40,86,112,0)');
  g.fillStyle = gr; g.fillRect(X0, Y0, FW, FH);

  // wooden table receding to a soft, out-of-focus back edge
  const yh = cy - 0.42 * R, hT = Y0 + FH - yh;
  gr = g.createLinearGradient(0, yh, 0, yh + hT);
  gr.addColorStop(0, '#1b0f09'); gr.addColorStop(0.4, '#25150c'); gr.addColorStop(1, '#180d07');
  g.fillStyle = gr; g.fillRect(X0, yh, FW, hT);
  const np = 9;
  for (let i = 0; i < np; i++) {
    const ya = yh + Math.pow(i / np, 1.55) * hT, yb = yh + Math.pow((i + 1) / np, 1.55) * hT, ph = yb - ya;
    const tone = 0.7 + r() * 0.6;
    g.fillStyle = rgba([58 * tone, 32 * tone, 17 * tone], 0.5);
    g.fillRect(X0, ya, FW, ph);
    const lines = Math.round(10 + ph * 0.28);
    for (let j = 0; j < lines; j++) {
      const ly = ya + r() * ph, dark = r() < 0.55;
      g.strokeStyle = dark ? 'rgba(6,3,1,' + (0.1 + r() * 0.16).toFixed(3) + ')' : 'rgba(170,110,64,' + (0.03 + r() * 0.06).toFixed(3) + ')';
      g.lineWidth = 0.5 + r() * Math.max(0.5, ph * 0.02);
      const p0 = r() * 10, fq = 0.002 + r() * 0.004, amp = (0.4 + r() * 1.4) * (0.4 + ph / 120);
      g.beginPath();
      for (let x = X0; x <= X0 + FW + 24; x += 24) {
        const yy = ly + Math.sin(x * fq + p0) * amp;
        if (x === X0) g.moveTo(x, yy); else g.lineTo(x, yy);
      }
      g.stroke();
    }
    const sh = Math.max(1, ph * 0.025);
    g.fillStyle = 'rgba(3,1,0,0.8)'; g.fillRect(X0, ya, FW, sh);
    g.fillStyle = 'rgba(200,130,74,0.06)'; g.fillRect(X0, ya + sh, FW, 1);
    const nj = 1 + ((r() * 2) | 0);
    for (let j = 0; j < nj; j++) { g.fillStyle = 'rgba(3,1,0,0.7)'; g.fillRect(X0 + r() * FW, ya, Math.max(1, ph * 0.018), ph); }
  }
  gr = g.createLinearGradient(0, yh - 2, 0, yh + 0.4 * R);
  gr.addColorStop(0, 'rgba(11,8,7,1)'); gr.addColorStop(1, 'rgba(11,8,7,0)');
  g.fillStyle = gr; g.fillRect(X0, yh - 2, FW, 0.4 * R + 2);

  // warm pool of light around the bowl, then darkness beyond it
  g.save();
  g.translate(cx, cy + 0.5 * R); g.scale(1, 0.4);
  gr = g.createRadialGradient(0, 0, 0, 0, 0, 1.9 * R);
  gr.addColorStop(0, 'rgba(255,150,70,0.24)'); gr.addColorStop(0.5, 'rgba(255,120,50,0.09)'); gr.addColorStop(1, 'rgba(255,100,40,0)');
  g.globalCompositeOperation = 'lighter';
  g.fillStyle = gr; g.fillRect(-3 * R, -3 * R, 6 * R, 6 * R);
  g.restore();

  g.save();
  g.translate(cx, cy + 0.15 * R); g.scale(1, 0.66);
  gr = g.createRadialGradient(0, 0, 1.2 * R, 0, 0, 3.0 * R);
  gr.addColorStop(0, 'rgba(5,3,2,0)'); gr.addColorStop(0.55, 'rgba(5,3,2,0.62)'); gr.addColorStop(1, 'rgba(5,3,2,0.95)');
  g.fillStyle = gr; g.fillRect(-4 * W, -4 * H, 8 * W, 8 * H);
  g.restore();

  // lantern glow behind the bowl
  g.save();
  g.translate(cx - 0.15 * R, cy - 0.8 * R); g.scale(1.25, 1);
  gr = g.createRadialGradient(0, 0, 0, 0, 0, 1.5 * R);
  gr.addColorStop(0, 'rgba(255,146,58,0.17)'); gr.addColorStop(0.45, 'rgba(255,120,44,0.07)'); gr.addColorStop(1, 'rgba(255,100,30,0)');
  g.globalCompositeOperation = 'lighter';
  g.fillStyle = gr; g.fillRect(-2 * R, -2 * R, 4 * R, 4 * R);
  g.restore();

  // bokeh
  const cols = [[255, 176, 84], [255, 138, 52], [255, 202, 124], [238, 96, 54], [255, 216, 150], [104, 166, 202]];
  const nb = Math.round(clamp(W * H / 60000, 10, 28));
  g.globalCompositeOperation = 'lighter';
  for (let i = 0; i < nb; i++) {
    const bx = X0 + r() * FW, by = Y0 + r() * (yh - Y0 + 0.05 * R);
    const br = (0.035 + 0.12 * Math.pow(r(), 1.8)) * R;
    const col = cols[r() < 0.15 ? 5 : (r() * 5) | 0];
    const edge = sstep(0.2, 1.2, Math.abs(bx - cx) / R);
    const a = (0.05 + 0.13 * r()) * (0.35 + 0.65 * edge);
    const bk = g.createRadialGradient(bx, by, 0, bx, by, br);
    bk.addColorStop(0, rgba(col, a * 0.8)); bk.addColorStop(0.72, rgba(col, a)); bk.addColorStop(0.92, rgba(col, a * 1.35)); bk.addColorStop(1, rgba(col, 0));
    g.fillStyle = bk; g.beginPath(); g.arc(bx, by, br, 0, TAU); g.fill();
  }
  g.globalCompositeOperation = 'source-over';
}

/* ---------- bowl & light ---------- */
const WALL = { dark: [5, 6, 9], lit: [96, 76, 62], spec: [255, 232, 206] };
const GLZ = { dark: [40, 11, 7], lit: [182, 68, 28], spec: [255, 196, 146] };
const RIM = { dark: [56, 17, 10], lit: [204, 88, 38], spec: [255, 222, 178] };
const FOOT = { dark: [24, 17, 13], lit: [98, 68, 48], spec: [200, 160, 120] };
const COOL = [48, 84, 120];

function updateLight(dt) {
  const t = anim.t;
  let tx, ty;
  if (reduce) { tx = -0.95; ty = -1.05; }
  else if (ptr.on) { tx = clamp((ptr.x - G.cx) / G.R, -1.7, 1.7); ty = clamp((ptr.y - G.cy) / G.R, -1.5, 1.0); }
  else { tx = -0.95 + Math.sin(t * 0.21) * 0.32 + Math.sin(t * 0.07) * 0.2; ty = -1.05 + Math.cos(t * 0.17) * 0.2; }
  const e = reduce ? 1 : 1 - Math.exp(-dt * 2.8);
  light.x += (tx - light.x) * e; light.y += (ty - light.y) * e;
  const fl = reduce ? 1 : 1 + 0.035 * Math.sin(t * 7.3) * Math.sin(t * 2.1 + 1) + 0.06 * (noise3(t * 1.1, 4.2, 9.1) - 0.5);
  light.I = fl * (1 + 0.16 * ptr.near);
  light.az = Math.atan2(light.y * 0.9 - 0.3, light.x);
  light.saz = Math.atan2(Math.sin(light.az) + 1, Math.cos(light.az));
}

// Horizontal gradient that shades the curved wall according to the light azimuth.
function wallGrad(g, c, specAmt, rw) {
  const gr = g.createLinearGradient(G.cx - rw, 0, G.cx + rw, 0), n = 18;
  for (let i = 0; i <= n; i++) {
    const t = i / n, th = Math.acos(clamp(-1 + 2 * t, -1, 1));
    const dif = Math.pow(Math.max(0, Math.cos(th - light.az)), 1.5);
    let col = mixc(c.dark, c.lit, clamp(dif * light.I * 0.9, 0, 1));
    col = mixc(col, c.spec, clamp(Math.pow(Math.max(0, Math.cos(th - light.saz)), 20) * specAmt * light.I, 0, 1));
    col = mixc(col, COOL, Math.pow(Math.max(0, Math.cos(th + 0.5)), 5) * 0.2);
    gr.addColorStop(t, rgb(col));
  }
  return gr;
}

function ringWedges(g, a0, a1) {
  const R = G.R, k = G.k, ri = RI * R, n = Math.max(2, Math.round((a1 - a0) / TAU * 110));
  for (let i = 0; i < n; i++) {
    const s = a0 + (a1 - a0) * i / n, e = a0 + (a1 - a0) * (i + 1) / n + 0.025, mid = (s + e) / 2;
    const dif = Math.max(0, Math.cos(mid - light.az));
    let col = mixc(RIM.dark, RIM.lit, clamp(Math.pow(dif, 1.3) * light.I * 0.9 + 0.08, 0, 1));
    col = mixc(col, RIM.spec, clamp(Math.pow(dif, 12) * 0.85 * light.I, 0, 1));
    g.fillStyle = rgb(col);
    g.beginPath();
    g.ellipse(G.cx, G.cy, R, R * k, 0, s, e);
    g.ellipse(G.cx, G.cy, ri, ri * k, 0, e, s, true);
    g.closePath();
    g.fill();
  }
}

function glazePath(g) {
  const R = G.R, N = G.drip.length - 1;
  g.beginPath();
  g.ellipse(G.cx, G.cy, R, R * G.k, 0, 0, PI);
  for (let i = N; i >= 0; i--) { const p = wallPt(PI * i / N, G.drip[i]); g.lineTo(p[0], p[1]); }
  g.closePath();
}

function drawGlow(g) {
  const Lx = G.cx + light.x * G.R, Ly = G.cy + light.y * G.R, rad = G.R * 1.7, I = light.I;
  const gr = g.createRadialGradient(Lx, Ly, 0, Lx, Ly, rad);
  gr.addColorStop(0, rgba([255, 178, 98], 0.2 * I)); gr.addColorStop(0.35, rgba([255, 142, 62], 0.085 * I)); gr.addColorStop(1, 'rgba(255,120,40,0)');
  g.globalCompositeOperation = 'lighter';
  g.fillStyle = gr;
  g.fillRect(Lx - rad, Ly - rad, 2 * rad, 2 * rad);
}

function drawShadow(g) {
  const R = G.R, y0 = G.cy + HB * R * G.ce;
  const sx = -Math.cos(light.az) * 0.28 * R, sy = Math.max(0, -Math.sin(light.az)) * 0.12 * R;
  g.save();
  g.translate(G.cx + sx, y0 + 0.05 * R + sy); g.scale(1, 0.34);
  let gr = g.createRadialGradient(0, 0, 0, 0, 0, 1.05 * R);
  gr.addColorStop(0, 'rgba(0,0,0,0.78)'); gr.addColorStop(0.55, 'rgba(0,0,0,0.5)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fillRect(-1.1 * R, -1.1 * R, 2.2 * R, 2.2 * R);
  g.restore();
  g.save();
  g.translate(G.cx, y0 + 0.1 * R * G.ce + 0.02 * R); g.scale(1, G.k * 0.9);
  gr = g.createRadialGradient(0, 0, 0.2 * R, 0, 0, 0.5 * R);
  gr.addColorStop(0, 'rgba(0,0,0,0.9)'); gr.addColorStop(1, 'rgba(0,0,0,0)');
  g.fillStyle = gr; g.fillRect(-0.5 * R, -0.5 * R, R, R);
  g.restore();
}

// Everything that sits behind the food: foot, back of the rim, far inner wall.
function drawBowlBack(g) {
  const R = G.R, k = G.k, cx = G.cx, cy = G.cy, ri = RI * R;
  const y0 = cy + HB * R * G.ce, hf = 0.1 * R * G.ce, rf = 0.36 * R;
  g.beginPath();
  g.moveTo(cx + rf, y0); g.lineTo(cx + rf, y0 + hf);
  g.ellipse(cx, y0 + hf, rf, rf * k, 0, 0, PI);
  g.lineTo(cx - rf, y0); g.closePath();
  g.fillStyle = wallGrad(g, FOOT, 0.2, rf); g.fill();

  ringWedges(g, PI, TAU);

  g.save();
  g.beginPath(); g.ellipse(cx, cy, ri, ri * k, 0, 0, TAU); g.clip();
  const top = cy - ri * k;
  let gr = g.createLinearGradient(0, top, 0, G.by);
  gr.addColorStop(0, '#0b0605'); gr.addColorStop(0.5, '#28120a'); gr.addColorStop(1, '#5c2b10');
  g.fillStyle = gr; g.fillRect(cx - ri, top, 2 * ri, ri * k * 2 + 0.2 * R);
  const front = clamp(0.35 + light.y * 0.9, 0, 1), hx = cx + clamp(light.x, -1, 1) * 0.55 * R, hy = cy - 0.3 * R;
  gr = g.createRadialGradient(hx, hy, 0, hx, hy, 0.6 * R);
  gr.addColorStop(0, rgba([255, 170, 96], 0.22 * front * light.I)); gr.addColorStop(1, 'rgba(255,150,80,0)');
  g.fillStyle = gr; g.fillRect(hx - 0.6 * R, hy - 0.6 * R, 1.2 * R, 1.2 * R);
  g.restore();

