/* ---------- broth: surface, oil, bubbles, ripples ---------- */
const drops = [], bubbles = [], ripples = [], clouds = [];
let nextBubble = 1, nextRipple = 2, lastHover = 0;

function initBroth() {
  const r = mulberry(31337);
  drops.length = 0; clouds.length = 0; bubbles.length = 0; ripples.length = 0;
  for (let i = 0; i < 44; i++) {
    drops.push({ a: r() * TAU, d: 0.12 + Math.sqrt(r()) * 0.74, w: (r() - 0.5) * 0.14, s: 0.011 + Math.pow(r(), 2.4) * 0.05, hot: r() < 0.32 });
  }
  for (let i = 0; i < 16; i++) {
    clouds.push({ x: (r() - 0.5) * 1.3, y: (r() - 0.5) * 1.3, r: 0.18 + r() * 0.32, sp: 0.04 + r() * 0.06, p: r() * TAU, q: r() * TAU, lit: r() < 0.6, a: 0.05 + r() * 0.09 });
  }
  for (let i = 0; i < 6; i++) {
    const a = r() * TAU, d = Math.sqrt(r()) * 0.75;
    bubbles.push({ u: Math.cos(a) * d, v: Math.sin(a) * d, r: 0.012 + r() * 0.02, t0: -r() * 2, life: 5 + r() * 3 });
  }
}

function addRipple(u, v, amp) {
  if (ripples.length > 26) ripples.shift();
  ripples.push({ u, v, t0: anim.t, amp });
}

function updateBroth(t) {
  if (reduce) return;
  for (let i = bubbles.length - 1; i >= 0; i--) {
    const b = bubbles[i];
    if (t - b.t0 > b.life) { addRipple(b.u, b.v, 0.22); bubbles.splice(i, 1); }
  }
  if (t > nextBubble && bubbles.length < 12) {
    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.8;
    bubbles.push({ u: Math.cos(a) * d, v: Math.sin(a) * d, r: 0.011 + Math.random() * 0.02, t0: t, life: 3 + Math.random() * 4 });
    nextBubble = t + 0.5 + Math.random() * 1.6;
  }
  if (t > nextRipple) {
    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.78;
    addRipple(Math.cos(a) * d, Math.sin(a) * d, 0.3 + Math.random() * 0.25);
    nextRipple = t + 1.6 + Math.random() * 2.8;
  }
  if (ptr.on && t - lastHover > 0.2) {
    const sp = Math.hypot(ptr.vx, ptr.vy);
    if (sp > 90) {
      const u = (ptr.x - G.cx) / G.R, v = (ptr.y - G.by) / (G.R * G.k);
      if (u * u + v * v < BR * BR * 0.92) { addRipple(u, v, clamp(sp / 1600, 0.12, 0.5)); lastHover = t; }
    }
  }
}

function drawBroth(g, t) {
  const R = G.R, br = BR * R, I = light.I, Ic = Math.min(1, I);
  g.save();
  g.translate(G.cx, G.by); g.scale(1, G.k);
  g.beginPath(); g.arc(0, 0, br, 0, TAU); g.clip();

  let gr = g.createRadialGradient(light.x * 0.12 * R, light.y * 0.1 * R - 0.05 * R, 0, 0, 0, br * 1.08);
  gr.addColorStop(0, '#c98a3a'); gr.addColorStop(0.42, '#a8651f'); gr.addColorStop(0.78, '#6e3812'); gr.addColorStop(1, '#3a1c08');
  g.fillStyle = gr; g.fillRect(-br, -br, 2 * br, 2 * br);

  for (const c of clouds) {
    const x = (c.x + Math.sin(t * c.sp + c.p) * 0.2) * R, y = (c.y + Math.cos(t * c.sp * 0.8 + c.q) * 0.2) * R;
    const rad = c.r * R * (1 + 0.12 * Math.sin(t * 0.23 + c.p)), col = c.lit ? [236, 172, 88] : [74, 34, 10];
    gr = g.createRadialGradient(x, y, 0, x, y, rad);
    gr.addColorStop(0, rgba(col, c.a)); gr.addColorStop(1, rgba(col, 0));
    g.fillStyle = gr; g.fillRect(x - rad, y - rad, 2 * rad, 2 * rad);
  }

  for (const d of drops) {
    const a = d.a + d.w * t;
    const x = Math.cos(a) * d.d * R + Math.sin(t * 0.4 + d.a * 5) * 0.006 * R, y = Math.sin(a) * d.d * R, rad = d.s * R;
