    g.stroke();
    g.fillStyle = rgba([255, 246, 220], 0.7 * Ic);
    g.beginPath(); g.arc(x + ox, y + oy, Math.max(0.5, rad * 0.2), 0, TAU); g.fill();
  }

  for (const b of bubbles) {
    const age = t - b.t0, e = sstep(0, 0.4, age) * (1 - sstep(b.life - 0.5, b.life, age));
    if (e <= 0.01) continue;
    const x = b.u * R + Math.sin(t * 0.6 + b.u * 9) * 0.004 * R, y = b.v * R, rad = b.r * R;
    g.lineWidth = Math.max(0.7, rad * 0.14);
    g.strokeStyle = rgba([255, 226, 170], 0.36 * e);
    g.fillStyle = rgba([255, 200, 120], 0.07 * e);
    g.beginPath(); g.arc(x, y, rad, 0, TAU); g.fill(); g.stroke();
    g.strokeStyle = rgba([40, 16, 4], 0.3 * e);
    g.beginPath(); g.arc(x, y, rad, 0.2, 1.6); g.stroke();
    g.fillStyle = rgba([255, 250, 230], 0.75 * e * Ic);
    g.beginPath(); g.arc(x - rad * 0.38, y - rad * 0.42, Math.max(0.5, rad * 0.2), 0, TAU); g.fill();
  }

  for (let i = ripples.length - 1; i >= 0; i--) {
    const q = ripples[i], age = t - q.t0;
    if (age > 2.4) { ripples.splice(i, 1); continue; }
    const a = q.amp * Math.pow(1 - age / 2.4, 1.6) * Math.min(1, age * 10);
    const rad = (0.015 + age * 0.26) * R, x = q.u * R, y = q.v * R;
    g.lineWidth = 0.011 * R; g.strokeStyle = rgba([48, 20, 6], 0.35 * a);
    g.beginPath(); g.arc(x, y, rad * 1.06, 0, TAU); g.stroke();
    g.lineWidth = 0.008 * R; g.strokeStyle = rgba([255, 222, 168], 0.45 * a);
    g.beginPath(); g.arc(x, y, rad, 0, TAU); g.stroke();
    g.lineWidth = 0.006 * R; g.strokeStyle = rgba([255, 222, 168], 0.2 * a);
    g.beginPath(); g.arc(x, y, rad * 0.66, 0, TAU); g.stroke();
  }

  gr = g.createRadialGradient(0, 0, br * 0.55, 0, 0, br * 1.02);
  gr.addColorStop(0, 'rgba(20,8,2,0)'); gr.addColorStop(0.7, 'rgba(20,8,2,0.28)'); gr.addColorStop(1, 'rgba(10,4,1,0.72)');
  g.fillStyle = gr; g.fillRect(-br, -br, 2 * br, 2 * br);

  // reflected lamp: a soft glow broken into rippling dashes
  const hu = clamp(light.x * 0.55, -0.62, 0.62) * R, hv = clamp(light.y * 0.42 - 0.1, -0.62, 0.36) * R, gs = 0.36 * R;
