    const w = (0.02 + 0.15 * hsh(i, 1, 2)) * env * R + 1.5, h = (0.0045 + 0.004 * hsh(i, 4, 1)) * R;
    const x = hu + ((hsh(i, 2, 5) - 0.5) * 0.09 + Math.sin(t * 0.9 + i * 1.7) * 0.012) * R;
    const y = hv + (f - 0.5) * 0.34 * R + Math.sin(t * 1.3 + i * 0.9) * 0.004 * R;
    const a = (0.25 + 0.45 * Math.pow(0.5 + 0.5 * Math.sin(t * 1.3 + i * 2.1), 0.7)) * env;
    g.fillStyle = rgba([255, 232, 184], a * 0.8 * Ic);
    g.beginPath(); g.ellipse(x, y, w / 2, h / 2, 0, 0, TAU); g.fill();
  }
  g.globalCompositeOperation = 'source-over';
  g.lineWidth = 0.02 * R; g.strokeStyle = rgba([255, 176, 92], 0.13 * I);
  g.beginPath(); g.arc(0, 0, br * 0.985, PI, TAU); g.stroke();
  g.restore();
}

/* ---------- noodles ---------- */
const MOUND = { u: 0.02, v: -0.16, a: 0.62, b: 0.4, h: 0.16 };
const NOOD = { deep: [140, 84, 30], wet: [180, 118, 50], mid: [226, 178, 102], lit: [250, 222, 158] };
const moundRho = (u, v) => Math.hypot((u - MOUND.u) / MOUND.a, (v - MOUND.v) / MOUND.b);
const moundH = (u, v) => { const rho = moundRho(u, v), q = 1 - rho * rho; return q > 0 ? MOUND.h * Math.pow(q, 0.55) : 0; };

function runPath(c, X, Y, V, n, thr, dx, dy) {
  c.beginPath();
  let pen = false;
  for (let i = 0; i <= n; i++) {
    if (V[i] > thr) {
      if (pen) c.lineTo(X[i] + dx, Y[i] + dy); else { c.moveTo(X[i] + dx, Y[i] + dy); pen = true; }
    } else pen = false;
  }
}

function drawMoundBase(g) {
  const R = G.R, k = G.k, M = MOUND, n = 16, bp = P(M.u, M.v, 0), r0 = M.a * R;
  g.save();
  g.translate(bp[0], bp[1]); g.scale(1, k * M.b / M.a);
  const gr = g.createRadialGradient(0, 0, r0 * 0.6, 0, 0, r0 * 1.18);
  gr.addColorStop(0, 'rgba(30,12,2,0.5)'); gr.addColorStop(1, 'rgba(30,12,2,0)');
  g.fillStyle = gr; g.fillRect(-r0 * 1.2, -r0 * 1.2, r0 * 2.4, r0 * 2.4);
  g.restore();
  for (let i = 0; i < n; i++) {
    const rho = 0.93 - i * (0.88 / (n - 1));
    const p = P(M.u, M.v, M.h * 0.9 * Math.pow(1 - rho * rho, 0.55) + 0.006);
    g.fillStyle = rgb(mixc(NOOD.deep, NOOD.wet, i / (n - 1)));
    g.beginPath(); g.ellipse(p[0], p[1], M.a * rho * R, M.b * rho * R * k, 0, 0, TAU); g.fill();
  }
}

function makeBundles(r) {
  const M = MOUND, out = [];
  for (let i = 0; i < 4; i++) {
    out.push({ layer: 0, u: M.u + (r() - 0.5) * 0.1, v: M.v + (i - 1.5) * 0.2 + (r() - 0.5) * 0.03, ang: 0.08 + (r() - 0.5) * 0.3, len: 1.5, bow: (r() - 0.5) * 0.1, amp: 0.02 + r() * 0.02, wl: 0.36 + r() * 0.14, ph: r() * TAU, m: 9 });
  }
  for (let i = 0; i < 6; i++) {
    const layer = i < 3 ? 1 : 2, a = r() * TAU, d = Math.sqrt(r()) * 0.6;
    out.push({ layer, u: M.u + Math.cos(a) * d * M.a * 0.75, v: M.v + Math.sin(a) * d * M.b * 0.75, ang: (layer === 1 ? -0.5 : 0.5) + (r() - 0.5) * 0.5, len: 1.5, bow: (r() - 0.5) * 0.12, amp: 0.02 + r() * 0.02, wl: 0.36 + r() * 0.14, ph: r() * TAU, m: 7 + ((r() * 3) | 0) });
  }
  out.sort((p, q) => p.layer - q.layer || p.v - q.v);
  return out;
}

function strokeStrand(g, gl, X, Y, H, V, n, w, tone, r) {
  g.lineCap = 'round'; g.lineJoin = 'round';
  g.lineWidth = w * 1.12; g.strokeStyle = 'rgba(30,10,2,0.4)';
  runPath(g, X, Y, V, n, 0.2, w * 0.1, w * 0.48); g.stroke();

  g.lineWidth = w;
  for (let i = 0; i < n; i++) {
    const vis = (V[i] + V[i + 1]) * 0.5;
    if (vis < 0.1) continue;
    const x0 = X[i], y0 = Y[i], x1 = X[i + 1], y1 = Y[i + 1];
    const dx = x1 - x0, dy = y1 - y0, len = Math.hypot(dx, dy) || 1;
    let nx = dy / len, ny = -dx / len;
    if (nx * -0.45 + ny * -0.9 < 0) { nx = -nx; ny = -ny; }
    const hn = clamp((H[i] + H[i + 1]) * 2.6, 0, 1);
    const c = mixc(NOOD.deep, mixc(NOOD.wet, NOOD.mid, sstep(0.05, 0.85, hn)), Math.pow(vis, 0.7));
    const col = [c[0] * tone, c[1] * tone, c[2] * tone], mx = (x0 + x1) / 2, my = (y0 + y1) / 2, hw = w / 2;
    const gr = g.createLinearGradient(mx + nx * hw, my + ny * hw, mx - nx * hw, my - ny * hw);
    gr.addColorStop(0, rgb(mixc(col, NOOD.lit, 0.4 + 0.3 * hn)));
    gr.addColorStop(0.4, rgb(col));
    gr.addColorStop(1, rgb(mixc(col, [84, 40, 10], 0.5)));
    g.strokeStyle = gr;
    g.beginPath(); g.moveTo(x0, y0); g.lineTo(x1, y1); g.stroke();
  }

  gl.lineCap = 'round'; gl.lineJoin = 'round';
  gl.globalCompositeOperation = 'destination-out';
  gl.lineWidth = w * 1.1; gl.strokeStyle = '#000';
  runPath(gl, X, Y, V, n, 0.1, 0, 0); gl.stroke();
  gl.globalCompositeOperation = 'source-over';
  gl.lineWidth = w * 0.16; gl.strokeStyle = 'rgba(255,238,196,0.34)';
  runPath(gl, X, Y, V, n, 0.6, -w * 0.06, -w * 0.3); gl.stroke();
  for (let q = 0; q < 2; q++) {
    const s0 = 3 + ((r() * (n - 12)) | 0), len = 3 + ((r() * 4) | 0);
    let ok = true;
    for (let i = s0; i <= s0 + len; i++) if (V[i] < 0.75) ok = false;
    if (!ok) continue;
    gl.lineWidth = w * 0.22; gl.strokeStyle = 'rgba(255,250,232,0.9)';
    gl.beginPath();
    for (let i = s0; i <= s0 + len; i++) { const x = X[i] - w * 0.08, y = Y[i] - w * 0.3; if (i === s0) gl.moveTo(x, y); else gl.lineTo(x, y); }
    gl.stroke();
  }
}

function drawNoodles(g, gl, r) {
  const w = 0.026 * G.R, n = 56, sp = 0.023;
  const X = new Float32Array(n + 1), Y = new Float32Array(n + 1), H = new Float32Array(n + 1), V = new Float32Array(n + 1);
  g.save(); gl.save();
  drawMoundBase(g);
  for (const B of makeBundles(r)) {
    const cs = Math.cos(B.ang), sn = Math.sin(B.ang);
    for (let j = 0; j < B.m; j++) {
      const lat0 = (j - (B.m - 1) / 2) * sp + (r() - 0.5) * 0.006, ph = B.ph + (r() - 0.5) * 0.5;
      const amp = B.amp * (0.9 + r() * 0.2), lift = 0.004 * r(), tone = 0.94 + r() * 0.12;
      for (let i = 0; i <= n; i++) {
