        const u = B.u + cs * l - sn * lat, v = B.v + sn * l + cs * lat;
        const rho = moundRho(u, v), nz = (noise3(u * 3.1 + 5, v * 3.1 + 9, 1.7) - 0.5) * 0.3;
        const h = moundH(u, v) * (0.84 + 0.05 * B.layer) + 0.009 + B.layer * 0.014 + lift, p = P(u, v, h);
