/* ---------- toppings I: helpers, nori, greens, menma ---------- */
const surf = (u, v) => moundH(u, v) * 0.9 + 0.014;

// shadowBlur / offsets are in device pixels, hence the dpr factor.
function withShadow(g, blur, ox, oy, a, fn) {
  const d = G.dpr;
  g.save();
  g.shadowColor = 'rgba(12,4,0,' + a + ')';
  g.shadowBlur = blur * d; g.shadowOffsetX = ox * d; g.shadowOffsetY = oy * d;
  fn();
  g.restore();
}

// Draw in bowl-plane units: fn sees x = right, y = toward viewer, both in units of R.
function flat(g, u, v, h, rot, fn) {
  const p = P(u, v, h);
  g.save(); g.translate(p[0], p[1]); g.scale(G.R, G.R * G.k); g.rotate(rot); fn(g); g.restore();
}

function extrude(g, u, v, h0, ht, rot, steps, sh, sideAt) {
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    flat(g, u, v, h0 + ht * t, rot, c => { c.beginPath(); sh(c); c.fillStyle = sideAt(t); c.fill(); });
  }
}

// A raised flat shape: soft shadow, stacked side walls, and a hole punched in the gloss map.
function slab(g, gl, u, v, h0, ht, rot, steps, sh, sideAt) {
  const R = G.R;
  withShadow(g, 0.03 * R, 0.008 * R, 0.028 * R, 0.6, () => flat(g, u, v, h0, rot, c => { c.beginPath(); sh(c); c.fillStyle = '#000'; c.fill(); }));
  extrude(g, u, v, h0, ht, rot, steps, sh, sideAt);
  for (let i = 0; i <= steps; i++) {
    flat(gl, u, v, h0 + ht * i / steps, rot, c => { c.globalCompositeOperation = 'destination-out'; c.beginPath(); sh(c); c.fillStyle = '#000'; c.fill(); });
  }
}

function nori(g, gl, c, bulge, r) {
  const N = 26, R = G.R;
  const at = (s, t) => {
    const u = lerp(lerp(c[0][0], c[1][0], s), lerp(c[3][0], c[2][0], s), t);
    const v = lerp(lerp(c[0][1], c[1][1], s), lerp(c[3][1], c[2][1], s), t) + bulge * Math.sin(PI * s) * (0.35 + 0.65 * t);
    return P(u, v, lerp(lerp(c[0][2], c[1][2], s), lerp(c[3][2], c[2][2], s), t));
  };
  const jag = [];
  for (let i = 0; i <= N; i++) jag.push(0.95 + (noise3(i * 0.45 + c[0][0] * 9, 2.1, c[0][1] * 5) - 0.5) * 0.1 + (r() - 0.5) * 0.02);
  const shape = cc => {
    cc.beginPath();
    for (let i = 0; i <= N; i++) { const p = at(i / N, 0); if (i) cc.lineTo(p[0], p[1]); else cc.moveTo(p[0], p[1]); }
    for (let i = N; i >= 0; i--) { const p = at(i / N, jag[i]); cc.lineTo(p[0], p[1]); }
    cc.closePath();
  };
  const bl = at(0, 0), br = at(1, 0), tl = at(0, 1), tr = at(1, 1), mid = [at(0, 0.55), at(1, 0.55)];
  const x0 = Math.min(bl[0], tl[0]) - 8, x1 = Math.max(br[0], tr[0]) + 8, y0 = Math.min(tl[1], tr[1]) - 8, y1 = Math.max(bl[1], br[1]) + 8;

  g.save();
  g.lineCap = 'round'; g.lineWidth = 0.05 * R; g.strokeStyle = 'rgba(20,8,0,0.4)';
  g.beginPath(); g.moveTo(bl[0], bl[1] + 0.01 * R); g.lineTo(br[0], br[1] + 0.01 * R); g.stroke();
  shape(g);
  let gr = g.createLinearGradient(tl[0], tl[1], br[0], br[1]);
  gr.addColorStop(0, '#3a5240'); gr.addColorStop(0.5, '#1b2b21'); gr.addColorStop(1, '#0b130e');
  g.fillStyle = gr; g.fill();
  g.clip();
  const yb = Math.max(bl[1], br[1]), yt = Math.min(mid[0][1], mid[1][1]);
  gr = g.createLinearGradient(0, yb, 0, yt);
  gr.addColorStop(0, 'rgba(24,14,4,0.7)'); gr.addColorStop(1, 'rgba(24,14,4,0)');
  g.fillStyle = gr; g.fillRect(x0, y0, x1 - x0, y1 - y0);
  for (let i = 0; i < 34; i++) {
    const s = r(), s2 = clamp(s + (r() - 0.5) * 0.05, 0, 1), p0 = at(s, 0.02 + r() * 0.1), p1 = at(s2, 0.7 + r() * 0.28);
    g.strokeStyle = r() < 0.5 ? 'rgba(120,160,128,0.09)' : 'rgba(0,0,0,0.22)';
    g.lineWidth = 0.6 + r() * 1.1;
    g.beginPath(); g.moveTo(p0[0], p0[1]); g.lineTo(p1[0], p1[1]); g.stroke();
  }
  g.restore();
  g.save();
  g.lineWidth = 1.3; g.strokeStyle = 'rgba(150,190,150,0.28)'; g.lineJoin = 'round';
  g.beginPath();
  for (let i = N; i >= 0; i--) { const p = at(i / N, jag[i]); if (i === N) g.moveTo(p[0], p[1]); else g.lineTo(p[0], p[1]); }
  g.stroke();
  g.restore();

  gl.save();
  shape(gl); gl.clip();
  const sg = gl.createLinearGradient(tl[0], 0, tr[0], 0);
  sg.addColorStop(0, 'rgba(170,220,180,0)'); sg.addColorStop(0.28, 'rgba(170,220,180,0.34)'); sg.addColorStop(0.5, 'rgba(170,220,180,0.05)'); sg.addColorStop(1, 'rgba(170,220,180,0)');
  gl.fillStyle = sg; gl.fillRect(x0, y0, x1 - x0, y1 - y0);
  gl.restore();
}

// Sheets that stand in the broth behind the noodle mound (drawn before the noodles).
function drawToppingsBack(g, gl, r) {
  g.save(); gl.save();
  nori(g, gl, [[-0.06, -0.72, 0], [0.34, -0.68, 0], [0.36, -0.74, 0.54], [-0.1, -0.77, 0.5]], 0.03, r);
  nori(g, gl, [[0.28, -0.64, 0], [0.58, -0.58, 0], [0.68, -0.6, 0.42], [0.34, -0.68, 0.47]], 0.035, r);
  g.restore(); gl.restore();
}

function leaf(g, gl, x, y, a, L, W) {
  const flip = (-0.45 * Math.sin(a) + 0.9 * Math.cos(a)) < 0 ? -1 : 1, R = G.R;
  const setup = c => { c.translate(x, y); c.rotate(a); c.scale(1, flip); };
  const blade = c => {
    c.beginPath();
    c.moveTo(0.32 * L, 0);
    c.bezierCurveTo(0.4 * L, -0.58 * W, 0.62 * L, -0.66 * W, 0.8 * L, -0.44 * W);
    c.bezierCurveTo(0.93 * L, -0.28 * W, L, -0.1 * W, L, 0);
    c.bezierCurveTo(L, 0.1 * W, 0.93 * L, 0.28 * W, 0.8 * L, 0.44 * W);
    c.bezierCurveTo(0.62 * L, 0.66 * W, 0.4 * L, 0.58 * W, 0.32 * L, 0);
    c.closePath();
  };
  const stem = c => {
    c.beginPath();
    c.moveTo(0, -0.2 * W); c.lineTo(0.5 * L, -0.15 * W); c.lineTo(0.5 * L, 0.15 * W); c.lineTo(0, 0.2 * W);
    c.quadraticCurveTo(-0.08 * W, 0, 0, -0.2 * W);
    c.closePath();
  };
  withShadow(g, 0.03 * R, 0.01 * R, 0.03 * R, 0.55, () => {
    g.save(); setup(g); g.fillStyle = '#000'; blade(g); g.fill(); stem(g); g.fill(); g.restore();
  });
  g.save(); setup(g);
  let gr = g.createLinearGradient(0, -0.2 * W, 0, 0.2 * W);
  gr.addColorStop(0, '#eef3cc'); gr.addColorStop(0.5, '#cfe0a2'); gr.addColorStop(1, '#93ad66');
  g.fillStyle = gr; stem(g); g.fill();
  gr = g.createLinearGradient(0, -0.62 * W, 0, 0.62 * W);
  gr.addColorStop(0, '#5aa444'); gr.addColorStop(0.55, '#2f7230'); gr.addColorStop(1, '#174d24');
  g.fillStyle = gr; blade(g); g.fill();
  gr = g.createLinearGradient(0.3 * L, 0, 0.55 * L, 0);
  gr.addColorStop(0, 'rgba(180,210,120,0.55)'); gr.addColorStop(1, 'rgba(180,210,120,0)');
  g.fillStyle = gr; blade(g); g.fill();
  g.lineCap = 'round';
  g.strokeStyle = 'rgba(214,232,160,0.8)'; g.lineWidth = Math.max(1, 0.05 * W);
  g.beginPath(); g.moveTo(0.34 * L, 0); g.lineTo(0.9 * L, 0); g.stroke();
  g.strokeStyle = 'rgba(200,230,150,0.28)'; g.lineWidth = Math.max(0.7, 0.014 * W);
  for (let i = 0; i < 6; i++) {
    const s = 0.42 + i * 0.09, e = 0.42 * W * (1 - Math.abs(s - 0.62) * 1.1);
    g.beginPath(); g.moveTo(s * L, 0); g.lineTo((s + 0.1) * L, -e); g.stroke();
    g.beginPath(); g.moveTo(s * L, 0); g.lineTo((s + 0.1) * L, e); g.stroke();
  }
  g.strokeStyle = 'rgba(190,235,140,0.32)'; g.lineWidth = 1.2; blade(g); g.stroke();
  g.restore();

  gl.save(); setup(gl);
  gl.globalCompositeOperation = 'destination-out'; gl.fillStyle = '#000';
  blade(gl); gl.fill(); stem(gl); gl.fill();
  gl.globalCompositeOperation = 'source-over';
  gl.lineCap = 'round'; gl.strokeStyle = 'rgba(220,255,200,0.5)'; gl.lineWidth = 0.09 * W;
  gl.beginPath(); gl.moveTo(0.5 * L, -0.2 * W); gl.lineTo(0.85 * L, -0.14 * W); gl.stroke();
  gl.restore();
}

function bokchoy(g, gl, u, v, ang, len, r) {
  const R = G.R, b = P(u, v, surf(u, v) + 0.006), leaves = [];
  for (let i = 0; i < 4; i++) leaves.push({ a: ang + (i - 1.5) * 0.3 + (r() - 0.5) * 0.08, L: len * R * (0.86 + r() * 0.28) });
  leaves.sort((p, q) => Math.sin(p.a) - Math.sin(q.a));
  for (const q of leaves) leaf(g, gl, b[0], b[1], q.a, q.L, q.L * (0.26 + r() * 0.05));
}

function menma(g, gl, r) {
  for (let i = 0; i < 5; i++) {
    const u = MOUND.u + (r() - 0.5) * 0.34, v = MOUND.v + (r() - 0.5) * 0.18, rot = (r() - 0.5) * 1.3;
    const len = 0.19 + r() * 0.07, wd = 0.048 + r() * 0.012, h0 = surf(u, v) + 0.006;
    const sh = c => rr(c, -len / 2, -wd / 2, len, wd, wd * 0.4);
    slab(g, gl, u, v, h0, 0.03, rot, 4, sh, t => rgb(mixc([150, 104, 52], [214, 168, 98], t)));
    flat(g, u, v, h0 + 0.03, rot, c => {
      c.beginPath(); sh(c); c.fillStyle = rgb([218, 172, 102]); c.fill();
      c.lineWidth = 0.006; c.strokeStyle = 'rgba(150,100,44,0.5)';
      for (let x = -len / 2 + 0.03; x < len / 2 - 0.02; x += 0.028) { c.beginPath(); c.moveTo(x, -wd * 0.4); c.lineTo(x + 0.004, wd * 0.4); c.stroke(); }
      c.strokeStyle = 'rgba(255,236,190,0.35)'; c.lineWidth = 0.007;
      c.beginPath(); c.moveTo(-len * 0.4, -wd * 0.28); c.lineTo(len * 0.4, -wd * 0.28); c.stroke();
    });
    flat(gl, u, v, h0 + 0.03, rot, c => {
      c.strokeStyle = 'rgba(255,240,200,0.55)'; c.lineWidth = 0.008; c.lineCap = 'round';
      c.beginPath(); c.moveTo(-len * 0.38, -wd * 0.25); c.lineTo(len * 0.38, -wd * 0.25); c.stroke();
    });
  }
}

/* ---------- toppings II: tofu, shiitake, corn, garnish ---------- */
// A shaded sphere-ish cap: radial gradient built in an unsquashed frame, then flattened by k.
function dome(g, x, y, rx, k, lx, ly, stops) {
  g.save(); g.translate(x, y); g.scale(1, k);
  const gr = g.createRadialGradient(lx * rx, ly * rx, 0, 0, 0, rx * 1.05);
  for (const s of stops) gr.addColorStop(s[0], s[1]);
  g.fillStyle = gr; g.beginPath(); g.arc(0, 0, rx, 0, TAU); g.fill();
  g.restore();
}

function tofu(g, gl, u, v, rot, w, d, r) {
  const ht = 0.07, h0 = surf(u, v) - 0.004, top = h0 + ht;
  const sh = c => rr(c, -w / 2, -d / 2, w, d, 0.03);
  slab(g, gl, u, v, h0, ht, rot, 8, sh, t => rgb(mixc([150, 102, 46], [216, 170, 96], t)));
  flat(g, u, v, top, rot, c => {
    c.beginPath(); sh(c);
    const gr = c.createRadialGradient(-w * 0.15, -d * 0.2, 0, 0, 0, w * 0.6);
    gr.addColorStop(0, '#f0c070'); gr.addColorStop(0.6, '#d6963e'); gr.addColorStop(1, '#a86a26');
    c.fillStyle = gr; c.fill();
    c.save(); c.clip();
    for (let i = 0; i < 9; i++) {
      const x = (r() - 0.5) * w * 0.9, y = (r() - 0.5) * d * 0.9, rx = 0.02 + r() * 0.05, ry = rx * (0.5 + r() * 0.5);
      c.fillStyle = 'rgba(112,58,14,' + (0.16 + r() * 0.2).toFixed(2) + ')';
      c.beginPath(); c.ellipse(x, y, rx, ry, r() * PI, 0, TAU); c.fill();
    }
    for (let i = 0; i < 46; i++) {
      const x = (r() - 0.5) * w, y = (r() - 0.5) * d, s = 0.002 + r() * 0.004;
      c.fillStyle = r() < 0.6 ? 'rgba(96,50,12,0.5)' : 'rgba(255,230,170,0.35)';
      c.beginPath(); c.arc(x, y, s, 0, TAU); c.fill();
    }
    c.restore();
    c.lineWidth = 0.008; c.strokeStyle = 'rgba(120,66,18,0.7)'; c.beginPath(); sh(c); c.stroke();
    for (let i = 0; i < 4; i++) {
      c.fillStyle = '#f2e8cc'; c.beginPath(); c.ellipse((r() - 0.5) * w * 0.7, (r() - 0.5) * d * 0.7, 0.008, 0.005, r() * PI, 0, TAU); c.fill();
    }
    const rx = (r() - 0.5) * w * 0.5, ry = (r() - 0.5) * d * 0.5;
    c.fillStyle = '#3f6c24'; c.beginPath(); c.arc(rx, ry + 0.006, 0.026, 0, TAU); c.fill();
    c.fillStyle = '#84b448'; c.beginPath(); c.arc(rx, ry, 0.026, 0, TAU); c.fill();
    c.fillStyle = '#c8de92'; c.beginPath(); c.arc(rx, ry, 0.019, 0, TAU); c.fill();
    c.fillStyle = 'rgba(46,28,8,0.7)'; c.beginPath(); c.arc(rx, ry, 0.013, 0, TAU); c.fill();
  });
  flat(gl, u, v, top, rot, c => {
    const gr = c.createLinearGradient(-w * 0.5, -d * 0.5, w * 0.3, d * 0.5);
    gr.addColorStop(0, 'rgba(255,236,190,0.5)'); gr.addColorStop(0.5, 'rgba(255,236,190,0.12)'); gr.addColorStop(1, 'rgba(255,236,190,0)');
    c.beginPath(); rr(c, -w / 2 + 0.01, -d / 2 + 0.01, w - 0.02, d - 0.02, 0.025); c.fillStyle = gr; c.fill();
    c.strokeStyle = 'rgba(255,248,224,0.7)'; c.lineWidth = 0.008; c.lineCap = 'round';
    c.beginPath(); c.moveTo(-w * 0.34, -d * 0.3); c.lineTo(-w * 0.06, -d * 0.34); c.stroke();
  });
}

function shiitake(g, gl, u, v, rad, r) {
  const R = G.R, k = G.k, h0 = surf(u, v), rot = r() * PI;
  const b = P(u, v, h0), t = P(u, v, h0 + 0.07), rx = rad * R, ry = rx * k, rt = rx * 0.9;
  const fillBody = c => {
    c.beginPath(); c.ellipse(b[0], b[1], rx, ry, 0, 0, TAU); c.fill();
    c.beginPath(); c.moveTo(b[0] - rx, b[1]); c.lineTo(t[0] - rt, t[1]); c.lineTo(t[0] + rt, t[1]); c.lineTo(b[0] + rx, b[1]); c.closePath(); c.fill();
  };
  withShadow(g, 0.035 * R, 0.01 * R, 0.03 * R, 0.6, () => { g.fillStyle = '#000'; g.beginPath(); g.ellipse(b[0], b[1], rx, ry, 0, 0, TAU); g.fill(); });
  const sg = g.createLinearGradient(b[0] - rx, 0, b[0] + rx, 0);
  sg.addColorStop(0, '#4c2c16'); sg.addColorStop(0.5, '#2c160a'); sg.addColorStop(1, '#180b05');
  g.fillStyle = sg; fillBody(g);
  dome(g, t[0], t[1], rt, k, -0.3, -0.4, [[0, '#9a6236'], [0.5, '#62361a'], [1, '#2e170a']]);
  g.save(); g.translate(t[0], t[1]); g.scale(1, k); g.rotate(rot);
  g.lineCap = 'round';
  const arms = 3 + ((r() * 2) | 0);
  for (let i = 0; i < arms; i++) {
    const a = i * PI / arms + (r() - 0.5) * 0.3, ca = Math.cos(a) * rt * 0.62, sa = Math.sin(a) * rt * 0.62;
    const qx = Math.cos(a + 1.5) * rt * 0.08, qy = Math.sin(a + 1.5) * rt * 0.08;
    g.strokeStyle = 'rgba(224,188,134,0.85)'; g.lineWidth = rt * 0.1;
    g.beginPath(); g.moveTo(-ca, -sa); g.quadraticCurveTo(qx, qy, ca, sa); g.stroke();
    g.strokeStyle = 'rgba(60,32,14,0.7)'; g.lineWidth = rt * 0.035;
    g.beginPath(); g.moveTo(-ca, -sa); g.quadraticCurveTo(qx, qy, ca, sa); g.stroke();
  }
  g.lineWidth = 1; g.strokeStyle = 'rgba(180,120,72,0.45)';
  g.beginPath(); g.arc(0, 0, rt * 0.985, 0, TAU); g.stroke();
  for (let i = 0; i < 3; i++) {
    g.fillStyle = '#efe4c6'; g.beginPath(); g.ellipse((r() - 0.5) * rt, (r() - 0.5) * rt, rt * 0.05, rt * 0.032, r() * PI, 0, TAU); g.fill();
  }
  g.restore();

  gl.save();
  gl.globalCompositeOperation = 'destination-out'; gl.fillStyle = '#000';
  gl.beginPath(); gl.ellipse(b[0], b[1], rx, ry, 0, 0, TAU); gl.fill();
  gl.beginPath(); gl.moveTo(b[0] - rx, b[1]); gl.lineTo(t[0] - rt, t[1]); gl.lineTo(t[0] + rt, t[1]); gl.lineTo(b[0] + rx, b[1]); gl.closePath(); gl.fill();
  gl.globalCompositeOperation = 'source-over';
  gl.translate(t[0] - rt * 0.28, t[1] - rt * k * 0.3); gl.scale(1, k);
  const gr = gl.createRadialGradient(0, 0, 0, 0, 0, rt * 0.55);
  gr.addColorStop(0, 'rgba(255,226,190,0.7)'); gr.addColorStop(1, 'rgba(255,226,190,0)');
  gl.fillStyle = gr; gl.beginPath(); gl.arc(0, 0, rt * 0.55, 0, TAU); gl.fill();
  gl.fillStyle = 'rgba(255,250,235,0.95)'; gl.beginPath(); gl.ellipse(-rt * 0.06, -rt * 0.05, rt * 0.07, rt * 0.045, -0.4, 0, TAU); gl.fill();
  gl.restore();
}

function corn(g, gl, u, v, r) {
  const R = G.R, k = G.k, ks = [];
  for (let i = 0; i < 17; i++) {
    const a = r() * TAU, d = Math.sqrt(r()) * 0.1;
    ks.push({ u: u + Math.cos(a) * d, v: v + Math.sin(a) * d * 0.85, s: 0.021 + r() * 0.008 });
  }
  ks.sort((p, q) => p.v - q.v);
  for (const q of ks) {
    const p = P(q.u, q.v, surf(q.u, q.v) + 0.012), rx = q.s * R;
    g.fillStyle = 'rgba(20,8,0,0.4)';
    g.beginPath(); g.ellipse(p[0] + rx * 0.25, p[1] + rx * 0.5, rx * 1.05, rx * 0.7, 0, 0, TAU); g.fill();
    dome(g, p[0], p[1] - rx * 0.2, rx, 0.85, -0.3, -0.35, [[0, '#fff0a0'], [0.4, '#f5c534'], [1, '#b27208']]);
    gl.save();
    gl.globalCompositeOperation = 'destination-out'; gl.fillStyle = '#000';
    gl.beginPath(); gl.ellipse(p[0], p[1] - rx * 0.1, rx * 1.05, rx * 0.9, 0, 0, TAU); gl.fill();
    gl.globalCompositeOperation = 'source-over';
    gl.fillStyle = 'rgba(255,255,240,0.95)';
    gl.beginPath(); gl.ellipse(p[0] - rx * 0.3, p[1] - rx * 0.45, rx * 0.26, rx * 0.16, -0.4, 0, TAU); gl.fill();
    gl.restore();
  }
}

function pickSpot(r, onMound) {
  let u = 0, v = 0;
  for (let t = 0; t < 14; t++) {
    const a = r() * TAU;
    if (onMound) { const d = Math.sqrt(r()) * 0.92; u = MOUND.u + Math.cos(a) * d * MOUND.a; v = MOUND.v + Math.sin(a) * d * MOUND.b; }
    else { const d = Math.sqrt(r()) * 0.8; u = Math.cos(a) * d; v = Math.sin(a) * d; }
    if (onMound || v > -0.45 || moundRho(u, v) < 1) break;
  }
  return [u, v];
}

function ring(g, u, v, h, s) {
  flat(g, u, v, h, 0, c => { c.fillStyle = 'rgba(20,8,0,0.32)'; c.beginPath(); c.arc(0.004, 0.012, s, 0, TAU); c.fill(); });
  flat(g, u, v, h, 0, c => { c.fillStyle = '#3f6c24'; c.beginPath(); c.arc(0, 0.006, s, 0, TAU); c.fill(); });
  flat(g, u, v, h + 0.008, 0, c => {
    c.fillStyle = '#84b448'; c.beginPath(); c.arc(0, 0, s, 0, TAU); c.fill();
    c.fillStyle = '#c8de92'; c.beginPath(); c.arc(0, 0, s * 0.74, 0, TAU); c.fill();
    c.fillStyle = 'rgba(46,28,8,0.7)'; c.beginPath(); c.arc(0, 0, s * 0.5, 0, TAU); c.fill();
  });
}

// Scallion rings, sesame, chili flakes and oil slicks scattered before the larger toppings go on.
function garnish(g, gl, r) {
  for (let i = 0; i < 7; i++) {
    const [u, v] = pickSpot(r, false);
    if (moundRho(u, v) < 1.08) continue;
    flat(g, u, v, 0.002, r() * PI, c => {
      const s = 0.05 + r() * 0.07, gr = c.createRadialGradient(0, 0, 0, 0, 0, s);
      gr.addColorStop(0, 'rgba(224,74,22,0.34)'); gr.addColorStop(0.7, 'rgba(210,66,20,0.16)'); gr.addColorStop(1, 'rgba(200,60,16,0)');
      c.fillStyle = gr; c.fillRect(-s, -s, 2 * s, 2 * s);
    });
  }
  for (let i = 0; i < 26; i++) {
    const [u, v] = pickSpot(r, i < 17), h = (moundRho(u, v) < 0.98 ? surf(u, v) : 0) + 0.004;
    ring(g, u, v, h, 0.024 + r() * 0.012);
  }
  for (let i = 0; i < 44; i++) {
    const [u, v] = pickSpot(r, i < 32), h = (moundRho(u, v) < 0.98 ? surf(u, v) : 0) + 0.004, seed = r() < 0.65, pick = r() < 0.5;
    flat(g, u, v, h, r() * PI, c => {
      if (seed) {
