305	function updateLight(dt) {
306	  const t = anim.t;
307	  let tx, ty;
308	  if (reduce) { tx = -0.95; ty = -1.05; }
309	  else if (ptr.on) { tx = clamp((ptr.x - G.cx) / G.R, -1.7, 1.7); ty = clamp((ptr.y - G.cy) / G.R, -1.5, 1.0); }
310	  else { tx = -0.95 + Math.sin(t * 0.21) * 0.32 + Math.sin(t * 0.07) * 0.2; ty = -1.05 + Math.cos(t * 0.17) * 0.2; }
311	  const e = reduce ? 1 : 1 - Math.exp(-dt * 2.8);
312	  light.x += (tx - light.x) * e; light.y += (ty - light.y) * e;
313	  const fl = reduce ? 1 : 1 + 0.035 * Math.sin(t * 7.3) * Math.sin(t * 2.1 + 1) + 0.06 * (noise3(t * 1.1, 4.2, 9.1) - 0.5);
314	  light.I = fl * (1 + 0.16 * ptr.near);
315	  light.az = Math.atan2(light.y * 0.9 - 0.3, light.x);
316	  light.saz = Math.atan2(Math.sin(light.az) + 1, Math.cos(light.az));
317	}
