319	// Horizontal gradient that shades the curved wall according to the light azimuth.
320	function wallGrad(g, c, specAmt, rw) {
321	  const gr = g.createLinearGradient(G.cx - rw, 0, G.cx + rw, 0), n = 18;
322	  for (let i = 0; i <= n; i++) {
323	    const t = i / n, th = Math.acos(clamp(-1 + 2 * t, -1, 1));
324	    const dif = Math.pow(Math.max(0, Math.cos(th - light.az)), 1.5);
325	    let col = mixc(c.dark, c.lit, clamp(dif * light.I * 0.9, 0, 1));
326	    col = mixc(col, c.spec, clamp(Math.pow(Math.max(0, Math.cos(th - light.saz)), 20) * specAmt * light.I, 0, 1));
327	    col = mixc(col, COOL, Math.pow(Math.max(0, Math.cos(th + 0.5)), 5) * 0.2);
328	    gr.addColorStop(t, rgb(col));
329	  }
330	  return gr;
331	}
