337	    const dif = Math.max(0, Math.cos(mid - light.az));
338	    let col = mixc(RIM.dark, RIM.lit, clamp(Math.pow(dif, 1.3) * light.I * 0.9 + 0.08, 0, 1));
339	    col = mixc(col, RIM.spec, clamp(Math.pow(dif, 12) * 0.85 * light.I, 0, 1));
