511	function updateBroth(t) {
512	  if (reduce) return;
513	  for (let i = bubbles.length - 1; i >= 0; i--) {
514	    const b = bubbles[i];
515	    if (t - b.t0 > b.life) { addRipple(b.u, b.v, 0.22); bubbles.splice(i, 1); }
516	  }
517	  if (t > nextBubble && bubbles.length < 12) {
518	    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.8;
519	    bubbles.push({ u: Math.cos(a) * d, v: Math.sin(a) * d, r: 0.011 + Math.random() * 0.02, t0: t, life: 3 + Math.random() * 4 });
520	    nextBubble = t + 0.5 + Math.random() * 1.6;
521	  }
522	  if (t > nextRipple) {
523	    const a = Math.random() * TAU, d = Math.sqrt(Math.random()) * 0.78;
