/* ---------- render, input, startup ---------- */
const mq = window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
const pt = { x: 0, y: 0 };
let baseFt = 1e3, nFrames = 0, rzTimer = 0, lastPar = '';

function drawContents(g) {
  const L = layers && layers.contents;
  if (L) g.drawImage(L.c, L.x, L.y, L.w, L.h);
}

function render(t) {
  if (stateDirty) { fxC.width = fxC.width; stateDirty = false; }
  const d = G.dpr;
  fx.setTransform(1, 0, 0, 1, 0, 0);
  fx.globalAlpha = 1; fx.globalCompositeOperation = 'source-over';
  fx.clearRect(0, 0, fxC.width, fxC.height);
  fx.setTransform(d, 0, 0, d, 0, 0);
  safe('shadow', drawShadow, fx);
  safe('back', drawBowlBack, fx);
  safe('broth', drawBroth, fx, t);
  safe('contents', drawContents, fx);
  safe('gloss', drawGloss, fx);
  safe('steam', drawSteam, fx);
  safe('front', drawBowlFront, fx);
  safe('glow', drawGlow, fx);
  safe('dust', drawDust, fx, t);
}

function upd(name, fn, a, b) {
  if (dead[name]) return;
  try { fn(a, b); } catch (e) { dead[name] = 1; if (window.console) console.error('[ramen] ' + name, e); }
}

function stepPointer(dt) {
  if (ptr.on) {
    const e = 1 - Math.exp(-dt * 20), nx = ptr.x + (pt.x - ptr.x) * e, ny = ptr.y + (pt.y - ptr.y) * e;
    const s = 1 - Math.exp(-dt * 12), iv = 1 / Math.max(dt, 0.004);
    ptr.vx += ((nx - ptr.x) * iv - ptr.vx) * s; ptr.vy += ((ny - ptr.y) * iv - ptr.vy) * s;
    ptr.x = nx; ptr.y = ny;
  } else {
    const s = Math.exp(-dt * 6);
    ptr.vx *= s; ptr.vy *= s;
  }
  const dx = (ptr.x - G.cx) / G.R, dy = (ptr.y - G.cy) / G.R;
  ptr.near += ((ptr.on ? Math.exp(-(dx * dx + dy * dy) * 0.5) : 0) - ptr.near) * (1 - Math.exp(-dt * 3));
