  const ty = ptr.on ? -(ptr.y / G.H - 0.5) * m : Math.cos(t * 0.07) * 0.2 * m;
  const pe = 1 - Math.exp(-dt * 2.2);
  par.x += (tx - par.x) * pe; par.y += (ty - par.y) * pe;
  const tf = 'translate3d(' + par.x.toFixed(2) + 'px,' + par.y.toFixed(2) + 'px,0)';
  if (tf !== lastPar) { bgC.style.transform = tf; lastPar = tf; }
}

// Sustained slow frames (relative to this device's own best) thin out the steam.
function adapt(raw, dt) {
  anim.ft += (raw - anim.ft) * 0.06;
  nFrames++;
  if (nFrames > 45) baseFt = Math.min(baseFt, anim.ft);
  const slow = nFrames > 90 && anim.ft > Math.max(24, baseFt * 1.5);
  anim.slow = slow ? anim.slow + dt : Math.max(0, anim.slow - dt);
  if (anim.slow > 1.5 && anim.q > 0.4) {
    anim.q = Math.max(0.4, anim.q - 0.2); anim.slow = 0;
    while (steam.length > MAXP * anim.q) pool.push(steam.pop());
  }
