  anim.raf = requestAnimationFrame(frame);
  const raw = Math.min(100, Math.max(0, now - anim.last)), dt = Math.min(0.05, raw / 1000);
  anim.last = now;
  anim.t += dt;
  adapt(raw, dt);
  upd('pointer', stepPointer, dt);
  upd('light', updateLight, dt);
  upd('brothStep', updateBroth, anim.t);
  upd('steamStep', stepSteam, dt, anim.t);
  render(anim.t);
}

function prewarm(sec) {
  while (steam.length) pool.push(steam.pop());
  emitAcc = 0;
  const n = Math.round(sec * 15);
  for (let i = 0; i < n; i++) stepSteam(1 / 15, anim.t + i / 15);
}

function renderStatic() {
  upd('light', updateLight, 0);
  render(1.5);
}

function setMode() {
  reduce = !!(mq && mq.matches);
  if (reduce) {
    if (anim.raf) { cancelAnimationFrame(anim.raf); anim.raf = 0; }
    ptr.on = false; ptr.near = 0; ptr.vx = ptr.vy = 0; par.x = par.y = 0;
    bgC.style.transform = ''; lastPar = '';
    prewarm(5);
    renderStatic();
  } else {
    if (!steam.length) prewarm(5);
    if (!anim.raf && !document.hidden) { anim.last = performance.now(); anim.raf = requestAnimationFrame(frame); }
  }
