function poke(x, y) {
  if (reduce) return;
  const u = (x - G.cx) / G.R, v = (y - G.by) / (G.R * G.k);
  if (u * u + v * v < BR * BR) { addRipple(u, v, 0.62); addRipple(u, v, 0.34, 0.16); }
