function engage(e) {
  pt.x = e.clientX; pt.y = e.clientY;
  if (!ptr.on && !reduce) { ptr.on = true; ptr.x = pt.x; ptr.y = pt.y; ptr.vx = 0; ptr.vy = 0; }
}

function onResize() {
  clearTimeout(rzTimer);
  rzTimer = setTimeout(() => {
    layout();
    prewarm(5);
    if (reduce) renderStatic();
  }, 140);
}

function onVisibility() {
  if (document.hidden) { if (anim.raf) { cancelAnimationFrame(anim.raf); anim.raf = 0; } }
  else if (!reduce && !anim.raf) { anim.last = performance.now(); anim.raf = requestAnimationFrame(frame); }
}

function makeGrain() {
  const c = document.createElement('canvas'); c.width = c.height = 128;
  const g = c.getContext('2d'), img = g.createImageData(128, 128), d = img.data, r = mulberry(909);
  for (let i = 0; i < 128 * 128; i++) {
    const white = r() < 0.5, j = i * 4;
    d[j] = d[j + 1] = d[j + 2] = white ? 255 : 0;
    d[j + 3] = Math.pow(r(), 2.2) * (white ? 16 : 30);
  }
  g.putImageData(img, 0, 0);
  document.getElementById('grain').style.backgroundImage = 'url(' + c.toDataURL('image/png') + ')';
}

function start() {
  tryDo(initSprites); tryDo(initBroth); tryDo(initDust); tryDo(makeGrain);
  layout();
  window.addEventListener('pointermove', engage, { passive: true });
  window.addEventListener('pointerdown', e => { engage(e); poke(e.clientX, e.clientY); }, { passive: true });
  window.addEventListener('pointerup', e => { if (e.pointerType !== 'mouse') ptr.on = false; }, { passive: true });
  window.addEventListener('pointercancel', () => { ptr.on = false; }, { passive: true });
  document.documentElement.addEventListener('pointerleave', () => { ptr.on = false; }, { passive: true });
  window.addEventListener('blur', () => { ptr.on = false; });
  window.addEventListener('resize', onResize);
  document.addEventListener('visibilitychange', onVisibility);
  if (mq) {
    if (mq.addEventListener) mq.addEventListener('change', setMode);
    else if (mq.addListener) mq.addListener(setMode);
  }
  setMode();
}

start();

